create temporary view dwd_base_${grass_region_without_quote} as
select
    user_id
    ,item_id
    ,order_id
    ,filter(
        coalesce(split(if(algo_tag = '', null, algo_tag), ','), array()),
        x -> x in ('DA_You May Also Like', 'DA_Daily Discover')
    ) AS scenario_tags
    ,filter(
        coalesce(split(if(source1_algo_tag = '', null, source1_algo_tag), ','), array()),
        x -> x in ('DA_You May Also Like', 'DA_Daily Discover')
    ) AS source1_scenario_tags
    ,filter(
        coalesce(split(if(source2_algo_tag = '', null, source2_algo_tag), ','), array()),
        x -> x in ('DA_You May Also Like', 'DA_Daily Discover')
    ) AS source2_scenario_tags
    ,event_timestamp / 1000 as order_event_time
from
    srdi_mart.dwd_sr_data_warehouse_platform
where
    grass_region = ${grass_region}
    and regional_date = ${regional_date}
    and operation = 'order'
    and (
        coalesce(algo_tag, '') != ''
        or coalesce(source1_algo_tag, '') != ''
        or coalesce(source2_algo_tag, '') != ''
    )
